import 'jest';
import { formatNumber } from '../../src';

describe('formatNumber()', () => {
    test('will format correctly given a prize of length 1', () => {
        expect(formatNumber(2)).toEqual('0,02');
    });
    test('will format correctly given a prize of length 2', () => {
        expect(formatNumber(45)).toEqual('0,45');
    });
    test('will format correctly given a larger prize length', () => {
        expect(formatNumber(1234567)).toEqual('12.345,67');
    });
    test('will format correctly given a prize larger than the max length allowed', () => {
        expect(formatNumber(1234567, 5)).toEqual('12.345');
    });
});